def rle_encode(s):
    parts = []
    i = 0
    n = len(s)
    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1
        parts.append(str(j - i) + s[i])
        i = j
    return ''.join(parts)


def rle_decode(s):
    result = []
    i = 0
    n = len(s)
    while i < n:
        start = i
        while i < n and '0' <= s[i] <= '9':
            i += 1
        digits = s[start:i]
        if not digits:
            raise ValueError('token has no run length')
        length = int(digits)
        if length <= 0:
            raise ValueError('run length must be positive')
        if i >= n:
            raise ValueError('dangling length')
        c = s[i]
        if not (('a' <= c <= 'z') or ('A' <= c <= 'Z')):
            raise ValueError('expected a letter')
        result.append(c * length)
        i += 1
    return ''.join(result)
